import { appendFileSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadConfig, loadEnvFile, getProjectDir, getDataDir, ConfigError } from './config.mjs';
import { filterAndClassify } from './filter.mjs';
import {
  loadStore,
  saveStore,
  diffSeen,
  markSeen,
  chainCounts,
  recordChainPost,
  setLoginWallAlerted,
  setBackoffAlerted,
  setEmptyResultsAlerted,
} from './store.mjs';
import {
  buildTweetMessage,
  buildChainMessage,
  buildAlertMessage,
  postToSlack,
} from './notify-slack.mjs';
import { planAnnouncements, summarizeChain } from './chain.mjs';
import { scrapeWatchSearches } from './search.mjs';
import { triage, MUTED, PRIORITY } from './tier.mjs';
import { classify, createClient } from './classify.mjs';
import { processReplies } from './replies.mjs';
import { fetchGithubStatus, describeGithubStatus } from './github-status.mjs';

const MAX_BACKOFF_MS = 30 * 60 * 1000;

// If a poll's raw scrape returns at least this many tweets, the result may
// have been truncated by X's own page size (roughly 20 entries per load) —
// scrapeSearch reads a single page and never scrolls. Worth a heads-up, not
// an alert: it's a visibility hint, not a failure.
const FULL_PAGE_HINT = 18;

// How many consecutive polls may scrape zero raw tweets — after a baseline
// that had previously seen at least one — before that looks like a broken
// extractor rather than a genuinely quiet account.
const EMPTY_SCRAPE_ALERT_THRESHOLD = 3;

// A broken pipe (terminal closed, Claude Code closed the inherited fd) must
// never take down this detached, unsupervised process — there's no
// supervisor to restart it, and a dead pid left in the pid file blocks
// hook-start from respawning until the next session.
process.stdout.on('error', () => {});
process.stderr.on('error', () => {});

const projectDir = getProjectDir();
const dataDir = getDataDir(projectDir);
loadEnvFile(projectDir);

// Mentions go to Slack and nowhere else. The operational diagnostics that used
// to print into the Claude Code terminal are appended here instead — without
// them a silent watcher would be undebuggable, and when Slack itself is the
// thing that's broken this file is the only place left to say so.
const logFile = join(dataDir, 'watch.log');

function logLine(message) {
  try {
    mkdirSync(dataDir, { recursive: true });
    appendFileSync(logFile, `${new Date().toISOString()} ${message}\n`);
  } catch {
    // Logging must never be the thing that kills the watcher.
  }
}

let config;
try {
  config = loadConfig();
} catch (err) {
  const message = err instanceof ConfigError ? err.message : String(err);
  logLine(`fatal: ${message}`);
  // Config failed, so there is no webhook to alert through — stderr is the
  // only channel left for a fatal startup error.
  process.stderr.write(`@entirehq mention watcher: ${message}\n`);
  process.exit(1);
}

// Register our own pid rather than relying on whoever spawned us. Under
// launchd nothing else writes this file, and the session hooks read it to
// decide whether a watcher is already up.
const pidFile = join(dataDir, 'watch.pid');
try {
  mkdirSync(dataDir, { recursive: true });
  writeFileSync(pidFile, String(process.pid));
} catch {
  // A missing pid file costs a duplicate-spawn check, not correctness.
}

const anthropic = createClient(config.anthropicApiKey);
if (!anthropic) {
  logLine('ANTHROPIC_API_KEY not set — triage runs on the deterministic score alone');
}

let store = loadStore(dataDir);
let consecutiveFailures = 0;
let consecutiveEmptyScrapes = 0;
let stopped = false;
let timer = null;
let wakeUp = null;
let replyFailureAlerted = false;

async function handleReplies(tweets) {
  try {
    await processReplies(tweets, config, {
      dataDir,
      shouldStop: () => stopped,
      log: logLine,
      alert: (message) => postToSlack(config.slackWebhookUrl, buildAlertMessage(message)),
    });
    replyFailureAlerted = false;
  } catch (error) {
    logLine(`replies paused: ${error.message}`);
    if (!replyFailureAlerted) {
      replyFailureAlerted = true;
      await postToSlack(config.slackWebhookUrl, buildAlertMessage(`Auto-replies paused: ${error.message}. Slack monitoring continues.`));
    }
  }
}

// Returns the tier decision, or null for a muted account. Muting is resolved
// before any API call so a muted handle costs nothing to skip.
async function decideOn(tweet) {
  const pre = triage(tweet, { mutedHandles: config.mutedHandles, teamHandles: config.teamHandles });
  if (pre.tier === MUTED) {
    logLine(`muted: @${tweet.author} ${tweet.url}`);
    return null;
  }

  const verdict = anthropic ? await classify(tweet, { client: anthropic }) : null;
  if (verdict && !verdict.ok) logLine(`triage degraded (${verdict.error}) — score only`);

  return triage(tweet, {
    mutedHandles: config.mutedHandles,
    teamHandles: config.teamHandles,
    verdict,
  });
}

async function announce(tweet, decision) {
  const result = await postToSlack(
    config.slackWebhookUrl,
    buildTweetMessage(tweet, decision, { handle: config.ownHandle, domain: config.brandDomain }),
  );
  const label = `${decision.tier}${decision.tier === PRIORITY ? ' \u2605' : ''} score=${decision.score}`;
  if (result.ok) {
    logLine(`slack ok [${label}]: @${tweet.author} ${tweet.kind} ${tweet.url}`);
  } else {
    logLine(`slack FAILED (status ${result.status}) [${label}]: @${tweet.author} ${tweet.url} — will retry next poll`);
  }
  return result.ok;
}

async function announceChain(chainId, entries) {
  const summary = summarizeChain(entries);
  const result = await postToSlack(config.slackWebhookUrl, buildChainMessage(summary));
  if (result.ok) {
    logLine(`slack ok [chain]: ${summary.count} collapsed from ${chainId}`);
  } else {
    logLine(
      `slack FAILED (status ${result.status}) [chain]: ${summary.count} from ${chainId} — will retry next poll`,
    );
  }
  return result.ok;
}

async function handleLoginWall() {
  logLine('login wall — X_AUTH_TOKEN / X_CSRF_TOKEN are stale; re-copy both cookies into .env and restart');
  if (!store.loginWallAlerted) {
    store = setLoginWallAlerted(store, true);
    saveStore(dataDir, store);
    await postToSlack(
      config.slackWebhookUrl,
      buildAlertMessage(
        '@entirehq mention watcher is not authenticated — the X session cookies expired. ' +
          'No mentions are being tracked until they are refreshed.',
      ),
    );
  }
}

async function pollOnce() {
  const { source, tweets, loginWall, searches } = await scrapeWatchSearches(config);

  if (loginWall) {
    await handleLoginWall();
    return { waitMs: MAX_BACKOFF_MS, tweets: null };
  }
  if (store.loginWallAlerted) {
    store = setLoginWallAlerted(store, false);
    saveStore(dataDir, store);
  }

  // The JSON path is the healthy one. Say so out loud when we fall back, so a
  // silent degradation in extraction quality is visible rather than guessed at.
  for (const search of searches) {
    logLine(`${search.name}: ${search.tweets.length} tweets via ${search.source}`);
    if (search.source === 'dom') logLine(`${search.name}: SearchTimeline JSON not seen — using the DOM fallback`);

    if (search.tweets.length >= FULL_PAGE_HINT) {
      logLine(
        `${search.name}: scraped ${search.tweets.length} tweets this poll — X returns one page (~20 entries); ` +
          'this result may be truncated and some mentions from this window could be missed',
      );
    }
  }

  // A previously non-empty baseline (some tweet was recorded at some point)
  // that suddenly scrapes zero raw tweets, repeatedly, looks like a broken
  // extractor or an exhausted Browserbase quota rather than a quiet account.
  const hadNonEmptyBaseline = store.baselined && store.seen.length > 0;
  if (tweets.length === 0 && hadNonEmptyBaseline) {
    consecutiveEmptyScrapes += 1;
  } else {
    consecutiveEmptyScrapes = 0;
    if (store.emptyResultsAlerted) {
      store = setEmptyResultsAlerted(store, false);
      saveStore(dataDir, store);
    }
  }

  if (consecutiveEmptyScrapes >= EMPTY_SCRAPE_ALERT_THRESHOLD && !store.emptyResultsAlerted) {
    store = setEmptyResultsAlerted(store, true);
    saveStore(dataDir, store);
    logLine(`${consecutiveEmptyScrapes} consecutive polls scraped zero tweets after a non-empty baseline — the extractor may be broken`);
    await postToSlack(
      config.slackWebhookUrl,
      buildAlertMessage(
        `@entirehq mention watcher has scraped zero tweets for ${consecutiveEmptyScrapes} consecutive polls after ` +
          'previously seeing mentions. Something is likely broken (extractor or Browserbase quota) — mentions are not being tracked.',
      ),
    );
  }

  const classified = filterAndClassify(tweets, config);
  const { isBaseline, fresh, store: nextStore } = diffSeen(store, classified);

  if (isBaseline) {
    store = nextStore;
    saveStore(dataDir, store);
    logLine(`baseline established — ${classified.length} tweets recorded, nothing announced`);
    return { waitMs: config.pollMs, tweets };
  }

  if (fresh.length === 0) {
    // Nothing new to announce, but ids diffSeen already folded in (e.g. from
    // this same batch) still need to be on disk.
    store = nextStore;
    saveStore(dataDir, store);
    logLine(`no new mentions (${classified.length} tracked, via ${source})`);
    return { waitMs: config.pollMs, tweets };
  }

  // Persist one tweet at a time, right after its announce attempt, instead
  // of marking the whole batch seen up front. The watcher is killed by a
  // SessionEnd hook every time a Claude Code session closes, so dying
  // mid-batch is routine, not exotic — if the batch were marked seen before
  // announcing, a death partway through would permanently lose the
  // unannounced remainder.
  //
  // A tweet is marked seen only once Slack has actually accepted it. Slack is
  // the sole delivery channel now, so marking a failed post as seen would drop
  // that mention permanently and silently. Leaving it unseen costs a duplicate
  // attempt next poll, which is the cheaper mistake.
  const decided = [];
  for (const tweet of fresh) {
    const decision = await decideOn(tweet);
    if (!decision) {
      store = markSeen(store, tweet.id);
      saveStore(dataDir, store);
      continue;
    }
    decided.push({ tweet, decision });
  }

  // Tiers are known before anything is posted, which is what lets a thread
  // past its budget collapse into one line without risking a priority
  // mention. It costs no extra classifier calls: every fresh mention was
  // already being classified one at a time.
  const plan = planAnnouncements(decided, {
    counts: chainCounts(store),
    limit: config.chainLimit,
  });

  for (const item of plan) {
    if (item.type === 'post') {
      if (!(await announce(item.tweet, item.decision))) continue;
      store = markSeen(store, item.tweet.id);
      // Charged only after Slack accepts it, so a bad Slack day cannot spend
      // a thread's budget on posts nobody saw.
      if (item.chainId) store = recordChainPost(store, item.chainId);
      saveStore(dataDir, store);
      continue;
    }

    if (!(await announceChain(item.chainId, item.entries))) continue;
    // The summary is the delivery for every mention in it, so they are only
    // seen once it lands.
    for (const entry of item.entries) store = markSeen(store, entry.tweet.id);
    saveStore(dataDir, store);
  }
  return { waitMs: config.pollMs, tweets };
}

function backoffMs() {
  return Math.min(config.pollMs * 2 ** consecutiveFailures, MAX_BACKOFF_MS);
}

async function loop() {
  logLine(`watcher started — polling every ${Math.round(config.pollMs / 1000)}s — ${projectDir}`);
  logLine(`auto-replies: ${config.replyMode}${config.replyHandle ? ` as @${config.replyHandle}` : ''}`);
  logLine(`search query: ${config.searchQuery}`);
  logLine(`GitHub reliability query: ${config.githubSearchQuery}`);
  logLine(`thread budget: ${config.chainLimit} individual posts per thread per 6h, then one summary line per poll`);

  while (!stopped) {
    let waitMs;
    const githubStatus = await fetchGithubStatus();
    logLine(describeGithubStatus(githubStatus));
    if (stopped) break;
    try {
      const batch = await pollOnce();
      waitMs = batch.waitMs;
      if (batch.tweets && !stopped) await handleReplies(batch.tweets);
      consecutiveFailures = 0;
      if (store.backoffAlerted) {
        store = setBackoffAlerted(store, false);
        saveStore(dataDir, store);
      }
    } catch (err) {
      consecutiveFailures += 1;
      waitMs = backoffMs();
      logLine(`scrape failed: ${err.message} — retrying in ${Math.round(waitMs / 1000)}s`);

      if (waitMs >= MAX_BACKOFF_MS && !store.backoffAlerted) {
        store = setBackoffAlerted(store, true);
        saveStore(dataDir, store);
        logLine('scrape failures have escalated to the 30-minute backoff cap — persistent failure, not a blip');
        await postToSlack(
          config.slackWebhookUrl,
          buildAlertMessage(
            '@entirehq mention watcher has hit the maximum retry backoff after repeated scrape failures. ' +
              'Mentions are not being tracked until this recovers.',
          ),
        );
      }
    }
    if (stopped) break;
    await new Promise((resolve) => {
      wakeUp = resolve;
      timer = setTimeout(resolve, waitMs);
    });
    timer = null;
    wakeUp = null;
  }
}

function shutdown() {
  stopped = true;
  if (timer) clearTimeout(timer);
  wakeUp?.();
  logLine('shutdown requested — finishing the current poll');
}

function finishShutdown() {
  try {
    rmSync(pidFile, { force: true });
  } catch {
    // Best effort — a stale pid file is handled by the liveness check.
  }
  logLine('watcher stopped');
  process.exit(0);
}

process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

// No supervisor sits above this detached process. An uncaught exception must
// be logged and swallowed here so a one-off bug in a single poll can't kill
// the whole watcher — it should log, keep the loop alive, and definitely
// never exit(2), which would leave a dead pid in the pid file that
// hook-start won't know to replace.
process.on('uncaughtException', (err) => {
  logLine(`uncaught exception: ${err?.message ?? err}`);
});

await loop();
finishShutdown();
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { homedir } from 'node:os';
import { getProjectDir, getDataDir } from './config.mjs';
import { LABEL, plistPath, buildPlist } from './launchd.mjs';

// Prefer the version-independent symlink over process.execPath, which points
// into a versioned Cellar directory that vanishes on the next node upgrade
// and would leave launchd running a binary that no longer exists.
function stableNodePath() {
  for (const candidate of ['/opt/homebrew/bin/node', '/usr/local/bin/node']) {
    if (existsSync(candidate)) return candidate;
  }
  return process.execPath;
}

const scriptsDir = dirname(fileURLToPath(import.meta.url));
const projectDir = resolve(getProjectDir());
const dataDir = getDataDir(projectDir);
const target = plistPath();

mkdirSync(dirname(target), { recursive: true });
mkdirSync(dataDir, { recursive: true });

const nodePath = stableNodePath();
writeFileSync(
  target,
  buildPlist({ nodePath, watchPath: join(scriptsDir, 'watch.mjs'), projectDir, dataDir }),
);

const domain = `gui/${process.getuid()}`;

function isLoaded() {
  try {
    execFileSync('launchctl', ['print', `${domain}/${LABEL}`], { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

// Tear down any previous instance first: bootstrap fails outright if the label
// is already loaded, and a stale one would keep running old settings.
try {
  execFileSync('launchctl', ['bootout', `${domain}/${LABEL}`], { stdio: 'ignore' });
} catch {
  // Not loaded — nothing to remove.
}

// bootout returns before launchd has finished releasing the label. Bootstrapping
// into that window fails with "Bootstrap failed: 5: Input/output error", which
// reads like a permissions problem and is really just a race.
const deadline = Date.now() + 10000;
while (isLoaded() && Date.now() < deadline) {
  execFileSync('sleep', ['0.25']);
}

try {
  execFileSync('launchctl', ['bootstrap', domain, target], { stdio: 'pipe' });
} catch (err) {
  const detail = err.stderr?.toString().trim() || err.message;
  console.error(`Failed to bootstrap the launch agent: ${detail}`);
  if (isLoaded()) console.error(`${LABEL} is still loaded — run: launchctl bootout ${domain}/${LABEL}`);
  process.exit(1);
}

console.log(`installed ${LABEL}`);
console.log(`  plist:   ${target}`);
console.log(`  node:    ${nodePath}`);
console.log(`  project: ${projectDir}`);
console.log(`  logs:    ${join(dataDir, 'watch.log')}`);
console.log('');
console.log('The watcher now runs independently of Claude Code: at login, across');
console.log('reboots, and restarted automatically if it dies. Stop it with:');
console.log('  npm run uninstall-agent');
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fetchGithubStatus, parseGithubStatus, describeGithubStatus, GITHUB_STATUS_URL } from '../scripts/github-status.mjs';

const summary = (extra = {}) => ({
  status: { indicator: 'none', description: 'All Systems Operational' },
  components: [{ name: 'Git Operations', status: 'operational' }],
  incidents: [],
  ...extra,
});
const incident = (extra = {}) => ({ name: 'API disruption', status: 'investigating', impact: 'major', ...extra });

test('operational status does not confirm an outage', () => {
  const status = parseGithubStatus(summary());
  assert.equal(status.ok, true);
  assert.equal(status.active, false);
  assert.match(describeGithubStatus(status), /no current disruption; replies held/);
});

test('degraded indicators, affected components, or active impactful incidents confirm a disruption', () => {
  for (const indicator of ['minor', 'major', 'critical']) {
    assert.equal(parseGithubStatus(summary({ status: { indicator, description: 'Disruption' } })).active, true);
  }
  for (const status of ['degraded_performance', 'partial_outage', 'major_outage']) {
    const result = parseGithubStatus(summary({ components: [{ name: 'Actions', status }] }));
    assert.equal(result.active, true);
    assert.match(describeGithubStatus(result), /Actions/);
  }
  for (const status of ['investigating', 'identified']) {
    const result = parseGithubStatus(summary({ incidents: [incident({ status })] }));
    assert.equal(result.active, true);
    assert.match(describeGithubStatus(result), /API disruption/);
  }
});

test('resolved, recovered, informational incidents and maintenance alone do not authorize replies', () => {
  for (const status of ['monitoring', 'resolved', 'postmortem']) {
    assert.equal(parseGithubStatus(summary({ incidents: [incident({ status })] })).active, false);
  }
  assert.equal(parseGithubStatus(summary({ incidents: [incident({ impact: 'none' })] })).active, false);
  assert.equal(parseGithubStatus(summary({
    status: { indicator: 'maintenance', description: 'Scheduled maintenance' },
    components: [{ name: 'Pages', status: 'under_maintenance' }],
  })).active, false);
});

test('missing or unfamiliar response fields fail closed', () => {
  for (const body of [null, {}, summary({ components: [] }), summary({ incidents: null }),
    summary({ status: { indicator: 'unexpected', description: 'Changed' } }),
    summary({ components: [{ name: 'Actions', status: 'unexpected' }] }),
    summary({ incidents: [incident({ status: 'unexpected' })] }),
    summary({ incidents: [incident({ impact: undefined })] })]) {
    assert.throws(() => parseGithubStatus(body), /Unexpected GitHub Status response/);
  }
});

test('fetch uses the public official summary, a timeout, and a fresh request', async () => {
  let calls = 0;
  const fetchImpl = async (url, options) => {
    calls++;
    assert.equal(url, GITHUB_STATUS_URL);
    assert.equal(url, 'https://www.githubstatus.com/api/v2/summary.json');
    assert.equal(options.headers['cache-control'], 'no-cache');
    assert.ok(options.signal instanceof AbortSignal);
    return { ok: true, json: async () => summary() };
  };
  const first = await fetchGithubStatus({ fetchImpl });
  await fetchGithubStatus({ fetchImpl });
  assert.equal(calls, 2);
  assert.equal(first.active, false);
  assert.ok(Number.isFinite(Date.parse(first.checkedAt)));
});

test('HTTP errors, invalid JSON, network failures and timeouts remain unknown, never outages', async () => {
  for (const fetchImpl of [
    async () => ({ ok: false, status: 503 }),
    async () => ({ ok: true, json: async () => { throw new Error('invalid JSON'); } }),
    async () => { throw new Error('network unavailable'); },
    async () => { throw new DOMException('timed out', 'TimeoutError'); },
    async () => ({ ok: true, json: async () => ({}) }),
  ]) {
    const status = await fetchGithubStatus({ fetchImpl });
    assert.equal(status.ok, false);
    assert.equal(status.active, false);
    assert.match(describeGithubStatus(status), /unavailable — replies held/);
  }
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import {
  buildTweetMessage,
  buildChainMessage,
  kindLabel,
  buildAlertMessage,
  escapeSlack,
  postToSlack,
} from '../scripts/notify-slack.mjs';

const tweet = {
  id: '1958000000000000001',
  author: 'somedev',
  text: 'hey @entirehq does this work with self-hosted runners?',
  url: 'https://x.com/somedev/status/1958000000000000001',
  createdAt: '2026-08-18T14:02:11.000Z',
  kind: 'reply',
};

// Starts a throwaway webhook receiver. `statuses` is consumed one entry per
// request, so [500, 200] models "fails once, then succeeds".
async function stubWebhook(statuses) {
  const received = [];
  const queue = [...statuses];
  const server = createServer((req, res) => {
    let raw = '';
    req.on('data', (chunk) => { raw += chunk; });
    req.on('end', () => {
      received.push(JSON.parse(raw));
      res.writeHead(queue.shift() ?? 200).end('ok');
    });
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const url = `http://127.0.0.1:${server.address().port}/hook`;
  return { url, received, close: () => new Promise((r) => server.close(r)) };
}

test('escapeSlack escapes the three mrkdwn control characters', () => {
  assert.equal(escapeSlack('a & b < c > d'), 'a &amp; b &lt; c &gt; d');
});

test('buildTweetMessage carries handle, kind, body and link', () => {
  const payload = buildTweetMessage(tweet);
  const json = JSON.stringify(payload);
  assert.match(json, /somedev/);
  assert.match(json, /reply/);
  assert.match(json, /self-hosted runners/);
  assert.match(json, /1958000000000000001/);
});

test('buildTweetMessage keeps the Slack link construct intact for a well-formed tweet', () => {
  // notify-slack.mjs interpolates author/id/url raw into `<url|text>`. This
  // pins the exact, unbroken construct for a normal tweet — the invariant
  // that parseTimelineJson's handle/id validation (scripts/parse.mjs) now
  // protects at the ingestion boundary.
  const payload = buildTweetMessage(tweet);
  const context = payload.blocks[1].elements[0].text;
  assert.ok(
    context.includes('<https://x.com/somedev/status/1958000000000000001|View on X>'),
    `expected an intact link construct, got: ${context}`,
  );
});

test('a priority fallback text is marked, because that is what a phone shows', () => {
  assert.equal(buildTweetMessage(tweet).text, '\u2605 REPLY \u00b7 @somedev replied to @entirehq');
  assert.equal(
    buildTweetMessage({ ...tweet, kind: 'mention' }).text,
    '\u2605 TWEET \u00b7 @somedev mentioned @entirehq',
  );
  assert.equal(
    buildTweetMessage({ ...tweet, kind: 'quote' }).text,
    '\u2605 QUOTE \u00b7 @somedev quoted @entirehq',
  );
});

test('a routine fallback text carries the kind but no priority marker', () => {
  const payload = buildTweetMessage(tweet, { tier: 'routine', reasons: [] });
  assert.equal(payload.text, 'REPLY \u00b7 @somedev replied to @entirehq');
});

test('kindLabel distinguishes a standalone tweet from a reply and a quote', () => {
  assert.equal(kindLabel('mention'), 'TWEET');
  assert.equal(kindLabel('reply'), 'REPLY');
  assert.equal(kindLabel('quote'), 'QUOTE');
  assert.equal(kindLabel(undefined), 'TWEET');
});

test('both tiers lead with the kind in the same slot', () => {
  for (const kind of ['mention', 'reply', 'quote']) {
    const label = kindLabel(kind);
    const priority = buildTweetMessage({ ...tweet, kind }, { tier: 'priority', reasons: [] });
    const routine = buildTweetMessage({ ...tweet, kind }, { tier: 'routine', reasons: [] });
    // The label must sit at the head of the rendered line, not mid-chain,
    // which is what made reply-vs-tweet unreadable at a glance.
    assert.match(priority.blocks[0].text.text, new RegExp(`^\\*\\u2605 \`${label}\``));
    assert.match(routine.blocks[0].elements[0].text, new RegExp(`^\`${label}\``));
  }
});

test('the kind is not repeated in the priority trailing chain', () => {
  const payload = buildTweetMessage(tweet, { tier: 'priority', reasons: ['question'] });
  const context = payload.blocks[1].elements[0].text;
  assert.doesNotMatch(context, /\breply\b/);
});

test('routine and priority render structurally different blocks', () => {
  const priority = buildTweetMessage(tweet, { tier: 'priority', reasons: ['question'] });
  const routine = buildTweetMessage(tweet, { tier: 'routine', reasons: ['question'] });
  // A skimming reader must be able to tell them apart without reading either.
  assert.equal(priority.blocks[0].type, 'section');
  assert.equal(routine.blocks[0].type, 'context');
  assert.equal(routine.blocks.length, 1);
});

test('a priority card shows reach and the triage reasons', () => {
  const payload = buildTweetMessage(
    { ...tweet, followers: 17388 },
    { tier: 'priority', reasons: ['17k followers', 'question'] },
  );
  const rendered = JSON.stringify(payload);
  assert.match(rendered, /17k followers/);
  assert.match(rendered, /question/);
});

test('reach is omitted rather than shown as zero when unknown', () => {
  const payload = buildTweetMessage({ ...tweet, followers: null }, { tier: 'priority', reasons: [] });
  assert.doesNotMatch(JSON.stringify(payload), /followers/);
});

test('a routine line still escapes user content', () => {
  const payload = buildTweetMessage(
    { ...tweet, text: '<https://evil.example|click me>' },
    { tier: 'routine', reasons: [] },
  );
  assert.match(JSON.stringify(payload), /&lt;https:\/\/evil\.example/);
  assert.doesNotMatch(JSON.stringify(payload), /\|click me>/);
});

test('buildTweetMessage escapes user content so a tweet cannot forge markup', () => {
  const payload = buildTweetMessage({ ...tweet, text: '<https://evil.example|click me>' });
  assert.match(JSON.stringify(payload), /&lt;https:\/\/evil\.example/);
});

test('buildAlertMessage produces a usable payload', () => {
  const payload = buildAlertMessage('X cookies expired');
  assert.equal(payload.text, 'X cookies expired');
  assert.ok(Array.isArray(payload.blocks) && payload.blocks.length > 0);
});

test('postToSlack posts the payload and reports success', async (t) => {
  const hook = await stubWebhook([200]);
  t.after(() => hook.close());
  const result = await postToSlack(hook.url, buildTweetMessage(tweet));
  assert.deepEqual({ ok: result.ok, attempts: result.attempts }, { ok: true, attempts: 1 });
  assert.equal(hook.received.length, 1);
  assert.equal(hook.received[0].text, '\u2605 REPLY \u00b7 @somedev replied to @entirehq');
});

test('postToSlack retries exactly once after a server error, then succeeds', async (t) => {
  const hook = await stubWebhook([500, 200]);
  t.after(() => hook.close());
  const result = await postToSlack(hook.url, buildTweetMessage(tweet), { retryDelayMs: 1 });
  assert.equal(result.ok, true);
  assert.equal(result.attempts, 2);
  assert.equal(hook.received.length, 2);
});

test('postToSlack gives up after the retry and resolves ok:false', async (t) => {
  const hook = await stubWebhook([500, 500]);
  t.after(() => hook.close());
  const result = await postToSlack(hook.url, buildTweetMessage(tweet), { retryDelayMs: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.status, 500);
  assert.equal(result.attempts, 2);
});

test('postToSlack resolves ok:false on a network error instead of throwing', async () => {
  const result = await postToSlack('http://127.0.0.1:1/hook', { text: 'x' }, { retryDelayMs: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.attempts, 2);
});

test('reach is not printed twice when a reason already names it', () => {
  const payload = buildTweetMessage(
    { ...tweet, followers: 17388 },
    { tier: 'priority', reasons: ['17k followers', 'not a follower'] },
  );
  const rendered = payload.blocks.map((b) =>
    b.type === 'section' ? b.text.text : b.elements.map((e) => e.text).join(' '),
  ).join(' ');
  assert.equal(rendered.match(/17k followers/g).length, 1);
});

const linkOnly = {
  ...tweet,
  kind: 'mention',
  matchedVia: 'link',
  text: 'finally moved our repos off github https://t.co/abc',
};

test('a link-only share does not claim the author tagged us', () => {
  // "replied to @entirehq" on a post that never tagged the account is a
  // factual error in the one line a phone notification shows.
  const payload = buildTweetMessage(linkOnly, { tier: 'priority', reasons: [] });
  assert.equal(payload.text, '\u2605 TWEET \u00b7 @somedev linked entire.io');
  assert.doesNotMatch(payload.text, /@entirehq/);
});

test('a link-only reply keeps its kind but still reports what it matched', () => {
  const payload = buildTweetMessage(
    { ...linkOnly, kind: 'reply' },
    { tier: 'routine', reasons: [] },
  );
  assert.equal(payload.text, 'REPLY \u00b7 @somedev linked entire.io');
});

test('a post that both tags and links reads as a mention and says it linked too', () => {
  const payload = buildTweetMessage(
    { ...linkOnly, matchedVia: 'both', kind: 'reply' },
    { tier: 'routine', reasons: [] },
  );
  assert.equal(payload.text, 'REPLY \u00b7 @somedev replied to @entirehq');
  assert.match(payload.blocks[0].elements[0].text, /links entire\.io/);
});

test('both tiers show the link tag in the channel, not just in the notification', () => {
  const priority = buildTweetMessage(linkOnly, { tier: 'priority', reasons: ['question'] });
  const routine = buildTweetMessage(linkOnly, { tier: 'routine', reasons: ['question'] });
  assert.match(priority.blocks[1].elements[0].text, /links entire\.io/);
  assert.match(routine.blocks[0].elements[0].text, /links entire\.io/);
});

test('a handle match carries no link tag', () => {
  const payload = buildTweetMessage(
    { ...tweet, matchedVia: 'handle' },
    { tier: 'routine', reasons: [] },
  );
  assert.doesNotMatch(payload.blocks[0].elements[0].text, /links/);
});

test('the brand names come from config, so a rename cannot leave stale text behind', () => {
  const brand = { handle: 'acmehq', domain: 'acme.dev' };
  assert.equal(
    buildTweetMessage(linkOnly, { tier: 'routine', reasons: [] }, brand).text,
    'TWEET \u00b7 @somedev linked acme.dev',
  );
  assert.equal(
    buildTweetMessage({ ...tweet, matchedVia: 'handle' }, { tier: 'routine', reasons: [] }, brand).text,
    'REPLY \u00b7 @somedev replied to @acmehq',
  );
});

test('a tweet with no match attribution still renders the pre-existing wording', () => {
  // Nothing persisted carries matchedVia, so a record read back from an older
  // store must not render as a link share.
  assert.equal(buildTweetMessage(tweet).text, '\u2605 REPLY \u00b7 @somedev replied to @entirehq');
});

test('a collapsed chain is one line that says how many it stands for', () => {
  const payload = buildChainMessage({
    count: 9,
    authors: ['Archilyte_', 'jennyoliver57', 'j3rah_'],
    moreAuthors: 4,
    url: 'https://x.com/Archilyte_/status/2111065254491000840',
  });
  assert.equal(payload.text, 'CHAIN \u00b7 9 more replies in this thread');
  assert.equal(payload.blocks.length, 1);
  assert.equal(payload.blocks[0].type, 'context');
  const line = payload.blocks[0].elements[0].text;
  assert.match(line, /^`CHAIN` 9 more replies in this thread/);
  assert.match(line, /@Archilyte_, @jennyoliver57, @j3rah_, \+4/);
  assert.ok(line.includes('<https://x.com/Archilyte_/status/2111065254491000840|open>'));
});

test('a collapsed chain of one reads as one reply, not one replies', () => {
  const payload = buildChainMessage({ count: 1, authors: ['ann'], moreAuthors: 0, url: 'https://x.com/ann/status/1' });
  assert.equal(payload.text, 'CHAIN \u00b7 1 more reply in this thread');
});

test('a collapsed chain names nobody rather than rendering an empty slot', () => {
  const line = buildChainMessage({ count: 2, authors: [], moreAuthors: 0, url: 'https://x.com/a/status/1' })
    .blocks[0].elements[0].text;
  assert.doesNotMatch(line, /\u00b7\s+\u00b7/);
});

test('a chain summary escapes handles so a chain line cannot forge markup either', () => {
  const line = buildChainMessage({
    count: 2,
    authors: ['<https://evil.example|click me>'],
    moreAuthors: 0,
    url: 'https://x.com/a/status/1',
  }).blocks[0].elements[0].text;
  assert.match(line, /&lt;https:\/\/evil\.example/);
  assert.doesNotMatch(line, /\|click me>/);
});
